 async function reviewAt(step,source=reviewRecord??selected(),eventIndex=null){
  if(!source)return;if(runner&&!runner.finished)throw Error(L('请先结束当前挑战。','Finish the current attempt first.'));
  if(!review||reviewRecord?.id!==source.id){review?.cancel();reviewRecord=source;review=new CityFlightReview(source,{createSim:createReviewSim});}
  const request=++reviewRequest,requestedReview=review;
  if(Number.isInteger(eventIndex))reviewEventIndex=Math.max(0,Math.min(source.events.length-1,eventIndex));
  else reviewEventIndex=Math.max(0,source.events.findLastIndex(event=>event.step<=step));
  reviewBusy=true;deck.hidden=false;renderReview();renderLearning();
  try{
   const event=source.events[reviewEventIndex]??source.events.at(-1);
   const returned=requestedReview.eligibility.exact?await onReview({record:source,event,step,review:requestedReview}):await requestedReview.seekStep(step);
   if(request!==reviewRequest)return null;reviewState=returned?.mode?returned:requestedReview.state;
   if(!reviewState||reviewState.cancelled)return null;preparedPractice=null;renderReview();return reviewState;
  }catch(error){if(request===reviewRequest){reviewState=null;deck.hidden=true;}throw error;}
  finally{if(request===reviewRequest){reviewBusy=false;renderReview();renderLearning();paintStatus();}}
 }
 async function learningAction(action,source=selected()){
  try{
   const r=source;
   if(action==='initial-practice'){await preparePractice(null);return;}
   if(action==='practice'){if(!r)throw Error(L('先完成一次练习或选择记录。','Finish a practice or select a record first.'));await preparePractice(r);return;}
   if(action==='return-live'){const isolated=getSessionMode()!=='live';cancel('pilot_cancel');reviewRequest++;review?.cancel();reviewBusy=false;await onReturn();preparedPractice=null;reviewRecord=null;reviewState=null;deck.hidden=true;postWatch=null;message=isolated?L('已返回复盘前的原现场，并保持暂停。','Returned to the original scene, paused.'):L('只读样本卡已关闭，原现场状态未改变。','Read-only sample card closed; the live scene state is unchanged.');render();return;}
   if(action==='compare'){const source=library.records.find(record=>record.id===$('compare-record').value);compareResult=compareCityAttempts(source,selected());renderLearning();return;}
   if(!r)throw Error(L('先完成一次尝试，失败和取消也可查看。','Complete an attempt first; failed and cancelled attempts can also be reviewed.'));
   let index=reviewEventIndex;if(!Number.isInteger(index)||index<0)index=r.events.length-1;
   if(action==='review'){const violation=r.events.findIndex(e=>e.type==='violation');index=violation>=0?violation:r.events.findIndex(e=>e.type==='stable_landing');if(index<0)index=r.events.length-1;if(r.id===selectedId)$('events').value=String(index);await reviewAt(Math.max(0,(r.events[index]?.step??r.stepCount)-360),r,index);}
   else if(action==='review-prev'||action==='review-next'){index=Math.max(0,Math.min(r.events.length-1,index+(action==='review-next'?1:-1)));await reviewAt(r.events[index].step,r,index);}
   else if(action==='review-before'||action==='review-exact')await reviewAt(Math.max(0,(r.events[index]?.step??r.stepCount)-(action==='review-before'?360:0)),r,index);
  }catch(error){message=error.message;notify(message,'warning');paintStatus();}
 }
