 function drawLines(canvas,series,cursor,aligned=false){
  let g;try{g=canvas.getContext('2d');}catch{}if(!g)return;const w=canvas.width,h=canvas.height,left=46,right=w-12,top=21,bottom=h-27;
  const points=series.flatMap(s=>s.rows).filter(s=>Number.isFinite(s.heightM)),times=points.map(s=>aligned?s.relativeTimeS:s.timeS);g.fillStyle='#0b1821';g.fillRect(0,0,w,h);g.font='13px sans-serif';if(!points.length)return;
  const minT=Math.min(0,...times),maxT=Math.max(1,...times),minY=Math.min(...points.map(s=>s.heightM))-.3,maxY=Math.max(...points.map(s=>s.heightM))+.3,x=t=>left+(right-left)*(t-minT)/(maxT-minT),y=v=>bottom-(bottom-top)*(v-minY)/(maxY-minY);
  g.strokeStyle='#2a424a';g.fillStyle='#9ab5c0';g.lineWidth=1;for(let i=0;i<3;i++){const value=minY+(maxY-minY)*i/2;g.beginPath();g.moveTo(left,y(value));g.lineTo(right,y(value));g.stroke();g.fillText(value.toFixed(1),3,y(value)+4);}g.fillText(L('世界高度 / m','World height / m'),left,14);
  series.forEach((s,index)=>{g.strokeStyle=['#a4e4ce','#e9bc80'][index%2];g.lineWidth=2;g.beginPath();let begun=false;for(const row of s.rows){if(!Number.isFinite(row.heightM)){begun=false;continue;}const time=aligned?row.relativeTimeS:row.timeS;if(begun)g.lineTo(x(time),y(row.heightM));else g.moveTo(x(time),y(row.heightM));begun=true;}g.stroke();g.fillStyle=g.strokeStyle;g.fillText(s.label,left+210+index*130,14);});
  if(Number.isFinite(cursor)){g.strokeStyle='#fff';g.beginPath();g.moveTo(x(cursor),top);g.lineTo(x(cursor),bottom);g.stroke();}g.fillStyle='#9ab5c0';g.fillText(minT.toFixed(1)+' s',left,h-5);g.fillText(maxT.toFixed(1)+' s',right-55,h-5);if(aligned)g.fillText(L('0 = 起飞事件；仅连接已存样本','0 = takeoff; lines join stored samples'),left+80,h-5);
 }
